import React from "react";
import "../Styles/Footer.css";

const Footer = () => {
  return (
    <footer className="footer">
      <div className="footer-content">
        {/* Left Brand */}
        <div className="footer-brand">
          <span className="footer-brand-main">UTAS</span>
          <span className="footer-brand-accent">Link</span>
        </div>

        {/* Middle Text */}
        <p className="footer-text">
          Connecting UTAS students with local businesses & ministries for
          flexible, real-world work.
        </p>

        {/* Right Contact */}
        <div className="footer-contact">
          <p>Get in touch</p>
          <p>• hello@UTASlink.om</p>
          <p>• +968 9xx xxx xx</p>
        </div>
      </div>

      {/* Bottom Line */}
      <div className="footer-copy">© 2025 UTASLink. All rights reserved.</div>
    </footer>
  );
};

export default Footer;
